<script setup lang="ts">import {onMounted,ref} from 'vue';import {request} from '../api/client';import {useTask} from '../hooks/useTask';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import MetricStrip from '../components/common/MetricStrip.vue';import PipeTable from '../components/common/PipeTable.vue';import BlueprintMap from '../components/BlueprintMap.vue';import {pct} from '../utils/format';const data=ref<any>(null);const {error,execute}=useTask();onMounted(()=>execute(async()=>{data.value=await request('/overview')}));</script><template><PageTitle eyebrow="01 / FIELD BRIEFING" title="今日巡检，从证据开始。" description="结合历史渗漏、压力波动与管材条件，推演城北运维的优先复查顺序。"/><Notice :error="error"/><template v-if="data"><MetricStrip :items="[{label:'纳入分析管段',value:data.pipes,note:'四个运维片区'},{label:'已完成推演',value:data.completed,note:'可复现的训练记录'},{label:'已批准计划',value:data.approved,note:'现场交接待执行'},{label:'留出集 ROC AUC',value:pct(data.latest_run?.result?.metrics.roc_auc),note:'25% 独立评估样本'}]"/><div class="overview-grid"><BlueprintMap :districts="data.districts"/><section class="field-note"><div class="eyebrow">DECISION NOTE / 01</div><h2>预算有限，<br>先走最值得的一段。</h2><p>今天的分析同时考虑漏检成本与误检成本。模型阈值只在训练折外概率上确定，留出集用于独立评价。</p><RouterLink class="link-action" to="/models">开始一次推演 ↗</RouterLink><div class="note-rule">概率用于排序，现场情况决定行动。</div></section></div><section class="section-block"><div class="section-heading"><h2>优先复查的管段</h2><RouterLink to="/results">查看完整评估 ↗</RouterLink></div><PipeTable :pipes="data.latest_run?.result?.ranking||[]" :limit="5"/></section></template><div v-else-if="!error" class="empty">正在读取分析范围…</div></template>
